import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { gsap } from 'gsap';
// Note: no need to import from three/tsl since we use MeshBasicNodeMaterial (non-TSL)

export default function createNode(config, ctx) {
  const group = new Group();

  // Shared cleanup array
  const cleanupFns = [];

  // --- 1. Parse text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  // Expect one item: "Get started"
  const textItem = items.find(item => item.role === 'headline') || items[0];
  const label = textItem?.text || 'Get started';
  const fontSize = textItem?.typography?.fontSize !== undefined
    ? textItem.typography.fontSize
    : 42; // fallback from spec
  const color = textItem?.color || '#e8ecf2'; // paper

  // --- 2. Create text object ---
  // Use ctx.fontAtlas.createText (sync)
  const textObject = ctx.fontAtlas.createText(label, {
    fontSize,
    color,
    align: 'center',
    // Add slight letter spacing for all-caps feel (though label is not all-caps)
    letterSpacingPx: 0.5
  });
  // Center text locally (it will be added to group)
  textObject.position.set(0, 0, 0.01); // slightly in front of plane
  group.add(textObject);

  // --- 3. Create background plane ---
  // Dimensions estimated to fit text: 2 x 0.5 units (generous padding)
  const planeWidth = 2.0;
  const planeHeight = 0.55;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: false,
    side: 2 // DoubleSide for visibility from any angle (but plane is flat)
  });
  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, 0, 0);
  group.add(mesh);

  // --- 4. Load brushed metal texture ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      material.map = texture;
      material.needsUpdate = true;
    }).catch(() => {
      // Fallback: solid surface color (not critical)
      material.color.setHex(0x2a2a2a);
    });
  } else {
    // No image fallback
    material.color.setHex(0x2a2a2a);
  }

  // --- 5. No cinematic primitives ---

  // --- 6. UserData ---
  group.userData.handlers = {}; // no events

  group.userData.cleanup = () => {
    cleanupFns.forEach(fn => fn());
    // Dispose material and geometry
    if (material.map) material.map.dispose();
    material.dispose();
    geometry.dispose();
    // Remove children (though caller should handle)
    while (group.children.length) {
      const child = group.children[0];
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (child.material.map) child.material.map.dispose();
        child.material.dispose();
      }
      group.remove(child);
    }
  };

  return group;
}
